using Path=std::filesystem::path;
static void phase(const char* label){std::cout<<"TOM_SOURCE_PHASE "<<label<<std::endl;}
static QString quote(const Path& p){auto s=QString::fromStdString(p.string());s.replace("'","'\\''");return "'"+s+"'";}
static void fakeTomDispatch(const Path& application,const Path& build,const Path& sys){auto loader=quote(sys/"usr/lib/ld-linux-aarch64.so.1"),libs=quote(sys/"usr/lib");auto script=QString("#!/bin/sh\nif [ \"$1\" = --tom ]; then\n exec %1 --library-path %2 %3 \"$@\"\nfi\nexec %1 --library-path %2 %4 \"$@\"\n").arg(loader,libs,quote(build/"tom-runtime-tests"),quote(application/"bin/helper-real"));underlay::atomicFile(application/"bin/reader-experience1-prepare",script.toUtf8());CHECK(chmod((application/"bin/reader-experience1-prepare").c_str(),0700)==0);}
static unsigned creates(const Path& root){auto log=root/"helper.log";return std::filesystem::exists(log)?unsigned(underlay::readBounded(log,65536).split('\n').count("create")):0;}
template<class Predicate>static void waitTom(ux::Shell& shell,Canvas& canvas,Predicate predicate){until([&]{shell.tick();canvas.changes();CHECK(!shell.failed());return shell.tomPanel()&&predicate(shell.tomPanel()->view());});}
static void settle(ux::Shell& shell,Canvas& canvas){waitTom(shell,canvas,[&](const tom::View& v){return v.ready&&v.configured&&!v.busy&&shell.tomPanel()->canLeave();});CHECK(shell.tomPanel()->view().error.isEmpty());}
static void press(ux::Shell& shell,Canvas& canvas,int id){if(shell.tomPanel()&&shell.tomPanel()->targets().rect(id).empty())std::fprintf(stderr,"PRESS_MISSING id=%d busy=%d active=%d request=%s answer=%d\n",id,shell.tomPanel()->view().busy,shell.tomPanel()->view().active,qPrintable(shell.tomPanel()->view().request),int(shell.tomPanel()->view().answer.size()));CHECK(uitest::tom(shell,id));shell.tick();canvas.changes();}
static input_event event(unsigned short type,unsigned short code,int value){input_event e{};e.type=type;e.code=code;e.value=value;return e;}
// The same Engine/consumeEvents OperationSink route used by the live Shell,
// driven exclusively by authored synthetic events (no device opened).
static void marker(ux::Shell& shell,Canvas& canvas,int y){CHECK(shell.writable());spike::Engine engine({{0,1619},{0,2159},1620,2160,0,false},shell.ink(),canvas);spike::FrameAssembler assembler;spike::Scheduler scheduler;spike::SessionStats stats;auto down=std::array{event(EV_KEY,BTN_TOOL_PEN,1),event(EV_ABS,ABS_X,200),event(EV_ABS,ABS_Y,y),event(EV_KEY,BTN_TOUCH,1),event(EV_SYN,SYN_REPORT,0)};CHECK(spike::consumeEvents(down,assembler,engine,scheduler,stats,1,nullptr,&shell));CHECK(shell.tomPanel()->contact()&&!shell.finger(1450,60,false));if(shell.document())CHECK(shell.document()->contact());auto move=std::array{event(EV_ABS,ABS_X,400),event(EV_SYN,SYN_REPORT,0)};CHECK(spike::consumeEvents(move,assembler,engine,scheduler,stats,8000001,nullptr,&shell));auto up=std::array{event(EV_KEY,BTN_TOUCH,0),event(EV_SYN,SYN_REPORT,0)};CHECK(spike::consumeEvents(up,assembler,engine,scheduler,stats,16000001,nullptr,&shell));CHECK(stats.contacts==1&&stats.released==1&&!shell.tomPanel()->contact());if(shell.document())CHECK(!shell.document()->contact());CHECK(engine.flush()==spike::Submit::Accepted);}
static void closeTom(ux::Shell& shell,Canvas& canvas,ux::State expected){settle(shell,canvas);CHECK(uitest::tom(shell,ib::tom::Close));shell.tick();canvas.changes();until([&]{shell.tick();canvas.changes();CHECK(!shell.failed());return !shell.tomPanel()->active()&&shell.state()==expected;});}
static void readerReady(ux::Shell& shell,Canvas& canvas){until([&]{shell.tick();canvas.changes();CHECK(!shell.failed());return shell.writable()&&shell.document()&&shell.styledInk()&&!shell.styledInk()->status().busy&&!shell.unsaved()&&!shell.semantics().pending();});}
static void navigate(ux::Shell& shell,Canvas& canvas,int page){if(shell.page()!=page){CHECK(shell.navigateTo(page));canvas.ready();}readerReady(shell,canvas);CHECK(shell.page()==page);}
static void openTom(ux::Shell& shell,Canvas& canvas){if(shell.document()){CHECK(shell.action(ux::Action::Show));canvas.changes();CHECK(uitest::menu(shell,ux::MenuTom));shell.tick();canvas.changes();}else CHECK(uitest::library(shell,ib::library::NavBase+int(ib::library::Section::Tom)));shell.tick();canvas.changes();settle(shell,canvas);CHECK(shell.tomPanel()->active());}
static void historyThread(ux::Shell& shell,Canvas& canvas,const QString& id){auto threads=shell.tomPanel()->view().threads;int row=-1;for(int i=0;i<threads.size();++i)if(threads[i].toObject()["id"]==id)row=i;CHECK(row>=0&&row<4);press(shell,canvas,ib::tom::History);press(shell,canvas,ib::tom::ThreadBase+row);waitTom(shell,canvas,[&](const auto& v){return v.thread==id;});settle(shell,canvas);}
static void sourceReturn(ux::Shell& shell,Canvas& canvas,int page){phase("sourceReturn tap SOURCE");press(shell,canvas,ib::tom::Source);phase("sourceReturn wait closed panel + target + writable");until([&]{shell.tick();canvas.changes();CHECK(!shell.failed());return !shell.tomPanel()->active()&&shell.document()&&shell.page()==page&&shell.writable();});phase("sourceReturn wait readerReady");readerReady(shell,canvas);shell.tick();canvas.changes();CHECK(shell.semantics().notice().isEmpty());phase("sourceReturn complete");}
static library::Document importBook(const Path& application,const Path& source,const Path& root,const char* name){underlay::privateDirectory(root/"inbox");std::filesystem::copy_file(source/"fixtures/library"/name,root/"inbox"/name);std::atomic<bool> stop{false};reader::syncLibrary(application,root,stop);auto books=library::documents(root);CHECK(books.size()==1);return books[0];}
static void apply(ux::Shell& shell,Canvas& canvas,ux::DocumentControls::EpubSettings settings){CHECK(shell.applyEpubView(settings));canvas.changes();canvas.ready();readerReady(shell,canvas);}
