 Path source=argv[1],parent=argv[2],build=argv[3],sys=argv[4];underlay::privateDirectory(parent);QTemporaryDir owned(QString::fromStdString((parent/"tom-source-route-XXXXXX").string()));CHECK(owned.isValid());owned.setAutoRemove(false);Path data=owned.path().toStdString();std::cout<<"TOM_SOURCE_ROUTE_DATA "<<data<<'\n';auto application=stage(source,data/"stage",build,sys);fakeTomDispatch(application,build,sys);
