  phase("EPUB return to Library");CHECK(shell.returnToLibrary());until([&]{shell.tick();canvas.changes();CHECK(!shell.failed());return shell.state()==ux::State::Picker&&!shell.document();});phase("EPUB Library reopen + History");openTom(shell,canvas);historyThread(shell,canvas,epubThread);CHECK(shell.tomPanel()->view().context==frozen&&!shell.tomPanel()->view().sourceMissing);phase("EPUB SOURCE return");sourceReturn(shell,canvas,target);CHECK(shell.document()->active().prepared.metadata["view_id"]==derived.id);
